const clean=(x,n=100)=>String(x??'').replace(/[\u0000-\u001f\u007f]/g,' ').trim().slice(0,n);
const rich=p=>Array.isArray(p?.title||p?.rich_text)?(p.title||p.rich_text).map(x=>x.plain_text||x.text?.content||'').join(''):'';
const validDate=s=>{if(typeof s!=='string'||!/^\d{4}-\d{2}-\d{2}(?:T(?:[01]\d|2[0-3]):[0-5]\d(?::[0-5]\d(?:\.\d+)?)?(?:Z|[+-](?:0\d|1[0-4]):[0-5]\d))?$/.test(s)||!Number.isFinite(Date.parse(s)))return false;const day=s.slice(0,10),d=new Date(day+'T00:00:00Z');return Number.isFinite(d.getTime())&&d.toISOString().slice(0,10)===day};
const safeJSON=x=>JSON.stringify(x).replace(/</g,'\\u003c').replace(/>/g,'\\u003e').replace(/&/g,'\\u0026').replace(/\u2028/g,'\\u2028').replace(/\u2029/g,'\\u2029');
const jstDay=d=>new Date(d.getTime()+9*3600000).toISOString().slice(0,10);
function calendarWindow(now){const a=Date.parse(jstDay(now)+'T00:00:00+09:00');return [new Date(a),new Date(a+31*86400000)]}
async function readCalendar(now,api){try{const [start,end]=calendarWindow(now);const raw=await api.between(start,end);if(!Array.isArray(raw)||raw.length>2000)throw Error('calendar');const events=[];const seen=new Set();for(const e of raw){if(!(e.startDate instanceof Date)||!(e.endDate instanceof Date)||!Number.isFinite(e.startDate.getTime())||!Number.isFinite(e.endDate.getTime())||e.endDate<e.startDate)throw Error('calendar');const key=String(e.identifier||'')+'|'+e.startDate.toISOString()+'|'+e.endDate.toISOString();if(e.identifier&&seen.has(key))continue;if(e.identifier)seen.add(key);events.push({title:clean(e.title,36)||'名称なし',start:e.startDate.toISOString(),end:e.endDate.toISOString(),allDay:e.isAllDay===true})}return {state:'ok',events}}catch{return {state:'error',events:[]}}}
function projectTask(row){if(row.archived||row.in_trash)return null;if(!row.properties||!/^(?:[0-9a-f]{32}|[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})$/i.test(String(row.id)))throw Error('task');const p=row.properties,title=clean(rich(p['やること']));if(!title)return null;const sync=rich(p['同期キー']);if(/^(?:yos-shift-|apple-calendar:|calendar:)/.test(sync))return null;const state=p['状態']?.select?.name||p['状態']?.status?.name;if(!STATES.has(state))throw Error('state');const date=p['期限']?.date;if(date&&(!validDate(date.start)||(date.end&&!validDate(date.end))||(date.end&&(date.end.includes('T')!==date.start.includes('T')||Date.parse(date.end)<Date.parse(date.start)))))throw Error('date');return {title,state,due:date?.start||null,end:date?.end||null,priority:clean(p['優先度']?.select?.name,20)}}
