async function resolveTaskSource(fileManager){
 try{const ids=new Set();let stores=[];for(const get of [()=>fileManager.iCloud(),()=>fileManager.local()]){try{const fm=get();if(fm&&fm.documentsDirectory())stores.push(fm)}catch{}}
 for(const fm of stores){const path=fm.joinPath(fm.documentsDirectory(),'YOS DAYSTREAM Notion.js');if(!fm.fileExists(path))continue;if(fm.isFileStoredIniCloud&&fm.isFileStoredIniCloud(path)&&fm.downloadFileFromiCloud)await fm.downloadFileFromiCloud(path);const raw=fm.readString(path);if(typeof raw!=='string'||raw.length>1500000)return null;const m=[...raw.matchAll(/^const SOURCE\s*=\s*['"]([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})['"]\s*;/gmi)];if(m.length!==1)return null;ids.add(m[0][1].toLowerCase())}
 return ids.size===1?[...ids][0]:null}catch{return null}
}
async function readTasks(keychain,RequestType,source){if(typeof source!=='string'||!/^([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})$/i.test(source))return {state:'unavailable',tasks:[]};let token;try{if(!keychain.contains(TOKEN_KEY))return {state:'unavailable',tasks:[]};token=keychain.get(TOKEN_KEY);if(typeof token!=='string'||!token.trim())return {state:'unavailable',tasks:[]};const tasks=[],seen=new Set(),cursors=new Set();let cursor=null;for(let i=0;i<4;i++){const req=new RequestType('https://api.notion.com/v1/data_sources/'+source+'/query');req.method='POST';req.timeoutInterval=5;req.headers={Authorization:'Bearer '+token,'Notion-Version':'2025-09-03','Content-Type':'application/json'};req.body=JSON.stringify({page_size:100,...(cursor?{start_cursor:cursor}:{})});const d=await req.loadJSON();if(req.response?.statusCode!==200||!Array.isArray(d?.results)||typeof d.has_more!=='boolean')throw Error('response');for(const r of d.results){const id=String(r.id).replace(/-/g,'').toLowerCase();if(seen.has(id))throw Error('duplicate');seen.add(id);const t=projectTask(r);if(t)tasks.push(t)}if(!d.has_more)return {state:'ok',tasks};if(typeof d.next_cursor!=='string'||!d.next_cursor||cursors.has(d.next_cursor))throw Error('cursor');cursor=d.next_cursor;cursors.add(cursor)}throw Error('limit')}catch{return {state:'error',tasks:[]}}finally{token=null}}
