function makeHandler(web,k,safari){return req=>{const url=String(req?.url||'');if(url==='about:blank'||url.startsWith('data:text/html'))return true;const m=/^https:\/\/yos-lifestyle\.invalid\/(open|theme)\/([a-zA-Z]+)$/.exec(url);if(!m)return false;if(m[1]==='theme'){if(!['black','cream'].includes(m[2]))return false;let ok=false;try{k.set(THEME_KEY,m[2]);ok=k.get(THEME_KEY)===m[2]}catch{}Promise.resolve().then(()=>web.evaluateJavaScript('nativeThemeResult('+String(ok)+','+JSON.stringify(m[2])+')')).catch(()=>{});return false}if(Object.prototype.hasOwnProperty.call(ROUTES,m[2])){try{safari.open(ROUTES[m[2]])}catch{Promise.resolve().then(()=>web.evaluateJavaScript("alert('起動できませんでした。既存アプリを直接開いてください。')")).catch(()=>{})}}return false}}
